import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"56. 链接多个文件","description":"The Little Book of C 中文版 — 56. 链接多个文件","frontmatter":{"title":"56. 链接多个文件","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","06-编译与构建","中文"],"description":"The Little Book of C 中文版 — 56. 链接多个文件","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":56,"sidebarWeight":56,"alternateZh":"/posts/c教程/zh-CN/06-编译与构建/056-Linking Multiple Files","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/056-Linking Multiple Files"},"headers":[],"relativePath":"posts/c教程/zh-CN/06-编译与构建/056-Linking Multiple Files.md","filePath":"posts/c教程/zh-CN/06-编译与构建/056-Linking Multiple Files.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/06-编译与构建/056-Linking Multiple Files.md"};function i(l,a,c,o,d,h){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/06-Compilation and Build/056-Linking Multiple Files)</p><p>当一个程序超出一个程序时<code>.c</code>文件中，编译器必须将它们组合成一个可执行文件。这个链接过程是将所有函数、变量和库引用连接到一个二进制文件中。</p><p>您已经看过它的片段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o math.o -o app</span></span></code></pre></div><p>但现在我们将更深入地了解链接的工作原理以及出现问题时会发生什么。</p><h4 id="步骤-1-两个编译阶段" tabindex="-1">步骤 1. 两个编译阶段 <a class="header-anchor" href="#步骤-1-两个编译阶段" aria-label="Permalink to &quot;步骤 1. 两个编译阶段&quot;">​</a></h4><p>每个 C 构建都有两个主要阶段：</p><p>编译 - 每个<code>.c</code>文件变成<code>.o</code>（目标文件）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c -o main.o</span></span>
<span class="line"><span>gcc -c math.c -o math.o</span></span></code></pre></div><p>每个<code>.o</code>文件包含机器代码和符号表（它定义的内容和需要的内容的列表）。</p><p>链接 – 链接器 (<code>ld</code>) 合并所有<code>.o</code>文件和库转换为可执行文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o math.o -o app</span></span></code></pre></div><p>如果缺少任何符号（例如未定义的函数），链接器将失败。</p><h4 id="步骤-2-什么是符号" tabindex="-1">步骤 2. 什么是符号？ <a class="header-anchor" href="#步骤-2-什么是符号" aria-label="Permalink to &quot;步骤 2. 什么是符号？&quot;">​</a></h4><p>符号是编译器用来跟踪函数和全局变量的名称。有两种：</p><ul><li>定义的符号 – 该文件提供的函数或变量。</li><li>未定义的符号——它需要从另一个文件中获取的东西。</li></ul><p>例子：</p><p>数学.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b) { return a + b; }</span></span></code></pre></div><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add(int, int);</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add(2, 3));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并链接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c</span></span>
<span class="line"><span>gcc -c math.c</span></span>
<span class="line"><span>gcc main.o math.o -o app</span></span></code></pre></div><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5</span></span></code></pre></div><p>如果您忘记链接<code>math.o</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -o app</span></span></code></pre></div><p>你会得到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>undefined reference to \`add&#39;</span></span></code></pre></div><h4 id="步骤-3-使用头文件进行声明" tabindex="-1">步骤 3. 使用头文件进行声明 <a class="header-anchor" href="#步骤-3-使用头文件进行声明" aria-label="Permalink to &quot;步骤 3. 使用头文件进行声明&quot;">​</a></h4><p>每个<code>.c</code>文件应在标头中声明（而不是定义）外部函数：</p><p>数学.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MATH_H</span></span>
<span class="line"><span>#define MATH_H</span></span>
<span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>然后将其包含在两者中<code>main.c</code>和<code>math.c</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;math.h&quot;</span></span></code></pre></div><p>这确保了声明和定义之间的一致性。</p><h4 id="步骤-4-链接目标文件和库" tabindex="-1">步骤 4. 链接目标文件和库 <a class="header-anchor" href="#步骤-4-链接目标文件和库" aria-label="Permalink to &quot;步骤 4. 链接目标文件和库&quot;">​</a></h4><p>您可以链接任意数量的<code>.o</code>文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o math.o util.o io.o -o app</span></span></code></pre></div><p>您还可以链接到库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -lm -o app</span></span></code></pre></div><p>(<code>-lm</code>链接数学库，提供如下功能<code>sqrt</code>,<code>sin</code>， ETC。）</p><p>这<code>-l</code>标记搜索<code>/usr/lib</code>和<code>/lib</code>默认情况下。</p><p>自定义库示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -L. -lmyutils -o app</span></span></code></pre></div><p>这里，<code>-L.</code>将当前目录添加到库搜索路径中，并且<code>-lmyutils</code>链接<code>libmyutils.a</code>或者<code>libmyutils.so</code>.</p><h4 id="步骤-5-链接顺序很重要" tabindex="-1">步骤 5. 链接顺序很重要 <a class="header-anchor" href="#步骤-5-链接顺序很重要" aria-label="Permalink to &quot;步骤 5. 链接顺序很重要&quot;">​</a></h4><p>链接器从左到右读取。如果在其定义出现之前使用符号，则可能会失败。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -lm main.o -o app    # ❌ wrong order</span></span>
<span class="line"><span>gcc main.o -lm -o app    # ✅ correct</span></span></code></pre></div><p>始终在需要库的目标文件之后列出库。</p><h4 id="步骤-6-拆分和链接多文件项目" tabindex="-1">步骤 6. 拆分和链接多文件项目 <a class="header-anchor" href="#步骤-6-拆分和链接多文件项目" aria-label="Permalink to &quot;步骤 6. 拆分和链接多文件项目&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project/</span></span>
<span class="line"><span>├── main.c</span></span>
<span class="line"><span>├── math.c</span></span>
<span class="line"><span>├── io.c</span></span>
<span class="line"><span>├── math.h</span></span>
<span class="line"><span>├── io.h</span></span>
<span class="line"><span>└── Makefile</span></span></code></pre></div><p>生成文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -Wall -std=c99</span></span>
<span class="line"><span>OBJ = main.o math.o io.o</span></span>
<span class="line"><span>TARGET = app</span></span>
<span class="line"><span>$(TARGET): $(OBJ)</span></span>
<span class="line"><span>    $(CC) $(OBJ) -o $(TARGET)</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(TARGET)</span></span></code></pre></div><p>现在，只需运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>./app</span></span></code></pre></div><p>Makefile 负责按顺序编译和链接所有内容。</p><h4 id="tiny-code-构建小型模块化程序" tabindex="-1">Tiny Code：构建小型模块化程序 <a class="header-anchor" href="#tiny-code-构建小型模块化程序" aria-label="Permalink to &quot;Tiny Code：构建小型模块化程序&quot;">​</a></h4><p>数学.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;math.h&quot;</span></span>
<span class="line"><span>int square(int x) { return x * x; }</span></span>
<span class="line"><span>int cube(int x) { return x * x * x; }</span></span></code></pre></div><p>数学.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MATH_H</span></span>
<span class="line"><span>#define MATH_H</span></span>
<span class="line"><span>int square(int x);</span></span>
<span class="line"><span>int cube(int x);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;math.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;square(3) = %d\\n&quot;, square(3));</span></span>
<span class="line"><span>    printf(&quot;cube(2) = %d\\n&quot;, cube(2));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>手动构建：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c math.c -o math.o</span></span>
<span class="line"><span>gcc -c main.c -o main.o</span></span>
<span class="line"><span>gcc main.o math.o -o app</span></span>
<span class="line"><span>./app</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>square(3) = 9</span></span>
<span class="line"><span>cube(2) = 8</span></span></code></pre></div><h4 id="步骤-7-静态链接与动态链接" tabindex="-1">步骤 7. 静态链接与动态链接 <a class="header-anchor" href="#步骤-7-静态链接与动态链接" aria-label="Permalink to &quot;步骤 7. 静态链接与动态链接&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>文件</th><th>描述</th></tr></thead><tbody><tr><td>静态</td><td><code>.a</code></td><td>代码被复制到可执行文件中</td></tr><tr><td>动态</td><td><code>.so</code></td><td>代码在运行时通过系统库共享</td></tr></tbody></table><p>静态链接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -L. -lmath -static -o app</span></span></code></pre></div><p>动态链接（默认）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o -L. -lmath -o app</span></span></code></pre></div><p>动态可执行文件较小，并且跨程序共享库。</p><h4 id="步骤-8-检查链接的二进制文件" tabindex="-1">步骤 8. 检查链接的二进制文件 <a class="header-anchor" href="#步骤-8-检查链接的二进制文件" aria-label="Permalink to &quot;步骤 8. 检查链接的二进制文件&quot;">​</a></h4><p>要查看哪些符号已定义或缺失：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nm main.o | head</span></span></code></pre></div><p>或者对于完整的二进制文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>objdump -t app | less</span></span>
<span class="line"><span>ldd app</span></span></code></pre></div><p><code>ldd</code>显示程序依赖哪些共享库。</p><h4 id="步骤-9-常见链接错误" tabindex="-1">步骤 9. 常见链接错误 <a class="header-anchor" href="#步骤-9-常见链接错误" aria-label="Permalink to &quot;步骤 9. 常见链接错误&quot;">​</a></h4><table tabindex="0"><thead><tr><th>错误</th><th>意义</th><th>修复</th></tr></thead><tbody><tr><td><code>undefined reference to </code></td><td>丢失的<code>.o</code>或图书馆</td><td>添加所有目标文件或更正<code>-l</code>旗帜</td></tr><tr><td><code>multiple definition of </code></td><td>多个文件中定义的相同函数</td><td>使用<code>extern</code>在声明中</td></tr><tr><td><code>cannot find -lfoo</code></td><td>缺少库文件</td><td>查看<code>-L</code>路径或安装开发包</td></tr><tr><td><code>relocation truncated</code></td><td>不匹配的架构</td><td>确保所有文件都是为同一目标构建的</td></tr></tbody></table><h4 id="步骤-10-内联与外部链接" tabindex="-1">步骤 10. 内联与外部链接 <a class="header-anchor" href="#步骤-10-内联与外部链接" aria-label="Permalink to &quot;步骤 10. 内联与外部链接&quot;">​</a></h4><p>内联函数定义为<code>static inline</code>标题中不需要链接，每个<code>.c</code>文件获得自己的副本。但功能正常<code>.c</code>文件必须仅链接一次。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>链接是你的程序变得完整的地方。它教你：</p><ul><li>如何<code>.o</code>和<code>.h</code>文件交互</li><li>库如何与您的二进制文件集成</li><li>如何调试丢失的符号和多个定义</li><li>模块化设计如何影响构建架构</li></ul><p>了解链接器对于构建可扩展的多文件系统（从小型实用程序到整个内核）至关重要。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>创建一个程序 3<code>.c</code>文件和 3<code>.h</code>文件。</li><li>故意省略一个目标文件并观察链接器错误。</li><li>使用<code>nm</code>检查每个函数的功能<code>.o</code>定义和参考。</li><li>构建静态库（<code>ar rcs libutils.a util.o</code>）并手动链接它。</li><li>使用<code>ldd</code>列出您编译的程序所依赖的共享库。</li></ol><p>接下来，您将学习如何创建和使用静态库和共享库，这是每个严肃的 C 项目所依赖的可重用性和可扩展性的模块化构建块。</p>`,93)])])}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
